# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HUZURLU BİR TOPLUM: TOPLUMSAL HUZURU SAĞLAYAN UNSURLAR (2.2.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">EMNİYET, GÜVEN, BARIŞ VE UZLAŞMA</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Emniyet ve Güven: Emaneti ehline vermek (Bakara 283)</text>\n  <text x="35" y="106" font-size="11.2" fill="#1e3a8a">  «Müslüman, elinden ve dilinden güvende olunan kimsedir.»</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Barış ve Uzlaşma (Sulh): Müminlerin arasını düzeltmek</text>\n  <text x="35" y="146" font-size="11.2" fill="#1e3a8a">  (Hucurât 9), kötülüğü iyilikle savmak (Fussilet 34)</text>\n  <text x="35" y="168" font-size="11.2" font-weight="bold" fill="#1e40af">• Tarihî Model: Medine Vesikası ve Ensar-Muhacir Kardeşliği</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ADALET, GÖRGÜ KURALLARI VE KARDEŞLİK</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Adalet ve Hak Gözetme: Her hak sahibine hakkını</text>\n  <text x="370" y="106" font-size="11.2" fill="#14532d">  vermek; düşmanlığa rağmen adil şahitlik (Mâide 8)</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• Görgü Kuralları (Âdâb-ı Muâşeret): İzin isteme,</text>\n  <text x="370" y="146" font-size="11.2" fill="#14532d">  selamlaşma, söz kesmeme, büyüklere saygı (Hucurât)</text>\n  <text x="370" y="168" font-size="11.2" fill="#14532d">• Kardeşlik ve Dayanışma: İyilik ve takvada yardımlaşma</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Muhakkak ki Allah adaleti, iyiliği ve akrabaya yardım etmeyi emreder...» (Nahl Suresi, 90. Ayet)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TOPLUMSAL HUZURU TEHDİT EDEN UNSURLAR VE KUL HAKKI (2.2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">ŞİDDET, TERÖR VE ÖTEKİLEŞTİRME</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Şiddet ve Terör: Fiziksel/psikolojik zorbalık ve</text>\n  <text x="35" y="106" font-size="11.2" fill="#713f12">  topluma korku salarak can/mal emniyetini tehdit etme</text>\n  <text x="35" y="128" font-size="11.2" fill="#713f12">• Yaşama Hakkı (Mâide 32): Haksız yere bir cana kıyan</text>\n  <text x="35" y="146" font-size="11.2" fill="#713f12">  bütün insanlığı öldürmüş gibidir.</text>\n  <text x="35" y="168" font-size="11.2" fill="#713f12">• Ötekileştirme: Dil, ırk, statü ayrımcılığı (Üstünlük takvadadır)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">DİL AFETLERİ, TECESSÜS VE BAĞIMLILIKLAR</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Yalan (Kizb), İftira (Bühtan) ve Gıybet (Hucurât 12)</text>\n  <text x="370" y="110" font-size="11.2" fill="#581c87">• Mahremiyet İhlali (Tecessüs): İnsanların gizli</text>\n  <text x="370" y="128" font-size="11.2" fill="#581c87">  hâllerini, kusurlarını ve kişisel verilerini araştırma</text>\n  <text x="370" y="150" font-size="11.2" fill="#581c87">• Zararlı Alışkanlıklar (İçki, Kumar — Mâide 90-91) ve</text>\n  <text x="370" y="168" font-size="11.2" fill="#581c87">  Dijital Bağımlılık (kontrolsüz ekran/oyun kullanımı)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Yalan, gıybet, iftira ve tecessüs kul hakkına girer; tövbenin yanında hak sahibiyle helalleşmeyi gerektirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ÖRNEK BİR ŞAHSİYET: BİLGE KRAL ALİYA İZZETBEGOVİÇ VE ADALET AHLAKI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">HAYATI, MÜCADELESİ VE ESERLERİ (1925-2003)</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Bosna-Hersek\'in ilk cumhurbaşkanı ve fikir insanı</text>\n  <text x="35" y="110" font-size="11.2" fill="#7c2d12">• Genç Müslümanlar (Mladi Muslimani) hareketinde</text>\n  <text x="35" y="128" font-size="11.2" fill="#7c2d12">  inanç, kimlik ve özgürlük mücadelesi</text>\n  <text x="35" y="150" font-size="11.2" fill="#7c2d12">• Başlıca Eserleri: Doğu ve Batı Arasında İslam,</text>\n  <text x="35" y="168" font-size="11.2" fill="#7c2d12">  İslam Deklarasyonu, Özgürlüğe Kaçışım (Notlar)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">SAVAŞTA BİLE AHLAK, HUKUK VE BİR ARADA YAŞAMA</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• 1992-1995 Bosna Savaşı\'nda İslam savaş hukukuna bağlılık:</text>\n  <text x="370" y="108" font-size="11.2" fill="#164e63">  «Kadınlara, çocuklara, yaşlılara ve ibadethanelere</text>\n  <text x="370" y="126" font-size="11.2" fill="#164e63">  asla dokunmayın; düşmanınıza benzemeyin!»</text>\n  <text x="370" y="148" font-size="11.2" fill="#164e63">• İntikam yerine adalet ve hukuk devleti ilkesini savundu.</text>\n  <text x="370" y="168" font-size="11.2" font-weight="bold" fill="#155e75">• Farklı din ve kültürlerin barış içinde yaşama modeli</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Biz kin ve intikam peşinde değiliz; yalnız adaletin yerini bulmasını istiyoruz.» (Aliya İzzetbegoviç)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
